<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowLeft, VideoPlay, Calendar, Timer, TrendCharts, User } from '@element-plus/icons-vue'
import type { AIFailureDiagnosis, DetectedBrowser, ExecutionLog, Task } from '../../../shared/types'
import type { AIProvider } from '../../../shared/schemas'
import { normalizeBaseUrl } from '../../../shared/aiProviders'
import { friendlyIpcMessage } from '../utils/apiError'

const route = useRoute(), router = useRouter(), task = ref<Task | null>(null), logs = ref<ExecutionLog[]>([]), running = ref(false), loginLoading = ref(false), browserDialog = ref(false), browserLoading = ref(false), diagnosisLoading = ref(false), diagnosisDialog = ref(false), diagnosis = ref<AIFailureDiagnosis | null>(null), diagnosisJson = ref(''), diagnosisSaving = ref(false)
const detectedBrowsers = ref<DetectedBrowser[]>([]), browserKey = ref(''), customPath = ref(''), profileMode = ref<'managed' | 'system'>('managed')
const statusLabel = (status: string | null) => ({ success: '成功', failed: '失败', running: '执行中', pending: '待执行' }[status ?? 'pending'] ?? '待执行')
const successRate = computed(() => logs.value.length ? Math.round(logs.value.filter((log) => log.status === 'success').length / logs.value.length * 100) : 0)
const localConfig = computed(() => { try { const config = JSON.parse(task.value?.config_json ?? '{}'); return config.local_browser_config ?? null } catch { return null } })
const browserOptions = computed(() => detectedBrowsers.value.flatMap((browser) => (browser.profiles.length ? browser.profiles : ['Default']).map((profile) => ({ key: `${browser.id}:${profile}`, label: `${browser.name} (${profile} Profile)`, browser, profile }))))
const format = (value: string | null) => value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(new Date(value)) : '—'
async function load(): Promise<void> { const data = await window.api.task.get(String(route.params.id)); task.value = data.task; logs.value = data.logs }
async function execute(): Promise<void> { if (!task.value) return; running.value = true; try { const result = await window.api.task.execute(task.value.id); result.success ? ElMessage.success(result.message) : ElMessage.warning(result.message); await load() } finally { running.value = false } }
async function promptLogin(): Promise<void> { if (!task.value) return; loginLoading.value = true; try { const result = await window.api.task.promptManualLogin(task.value.id); ElMessage.info(`状态已保存（${result.count} 个站点 Cookie），正在验证自动签到流程…`); const verification = await window.api.task.execute(task.value.id); verification.success ? ElMessage.success('首次引导完成，自动签到流程已验证，以后会直接复用') : ElMessage.warning(`登录状态已保留，但自动流程验证未通过：${verification.message}`); await load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : String(error)) } finally { loginLoading.value = false } }
async function openBrowserSettings(): Promise<void> { browserLoading.value = true; browserDialog.value = true; try { detectedBrowsers.value = await window.api.system.getDetectedBrowsers(); const current = localConfig.value; profileMode.value = current?.profileMode === 'system' ? 'system' : 'managed'; browserKey.value = current?.browserId ? `${current.browserId}:${current.profileName || 'Default'}` : ''; customPath.value = current?.userDataDir ?? '' } finally { browserLoading.value = false } }
async function saveBrowserSettings(): Promise<void> { if (!task.value) return; const option = browserOptions.value.find((item) => item.key === browserKey.value); const browser = option?.browser ?? detectedBrowsers.value[0]; const userDataDir = browserKey.value === 'custom' ? customPath.value.trim() : option?.browser.userDataDir; if (profileMode.value === 'system' && !userDataDir) { ElMessage.warning('请选择浏览器 Profile 或填写自定义路径'); return }; if (!browser?.executablePath) { ElMessage.warning('未检测到原生 Chrome 或 Edge'); return }; let existing: Record<string, unknown> = {}; try { existing = JSON.parse(task.value.config_json || '{}') } catch { /* ignore */ }; const local_browser_config = { profileMode: profileMode.value, browserId: browser.id, channel: browser.channel, executablePath: browser.executablePath, userDataDir: profileMode.value === 'system' ? userDataDir : undefined, profileName: profileMode.value === 'system' ? (option?.profile ?? 'Default') : 'Default' }; await window.api.task.update(task.value.id, { loginType: 'local_browser', config: { ...existing, local_browser_config } }); browserDialog.value = false; ElMessage.success(profileMode.value === 'managed' ? '已启用 AutoCheckin 专用登录档案，请进行一次引导登录' : '本地浏览器配置已保存'); await load() }
async function diagnoseFailure(): Promise<void> { if (!task.value) return; diagnosisLoading.value = true; try { const [provider, baseUrl, model, apiKey] = await Promise.all([window.api.config.get('ai_provider'), window.api.config.get('ai_base_url'), window.api.config.get('ai_model'), window.api.config.get('ai_api_key')]); if (!provider || !baseUrl || !model) throw new Error('请先在设置中完成 AI API 配置。'); diagnosis.value = await window.api.ai.diagnoseTask({ id: task.value.id, provider: provider as AIProvider, baseUrl: normalizeBaseUrl(baseUrl), model, apiKey: apiKey ?? '' }); diagnosisJson.value = JSON.stringify(diagnosis.value.adapter, null, 2); diagnosisDialog.value = true } catch (error) { ElMessage.error(friendlyIpcMessage(error)) } finally { diagnosisLoading.value = false } }
async function refineDiagnosis(): Promise<void> { if (!diagnosis.value) return; diagnosisSaving.value = true; try { const [provider, baseUrl, model, apiKey] = await Promise.all([window.api.config.get('ai_provider'), window.api.config.get('ai_base_url'), window.api.config.get('ai_model'), window.api.config.get('ai_api_key')]); if (!provider || !baseUrl || !model) throw new Error('请先在设置中完成 AI API 配置。'); const refined = await window.api.ai.refineDiagnosis({ adapter: JSON.parse(diagnosisJson.value), inspection: diagnosis.value.inspection, provider: provider as AIProvider, baseUrl: normalizeBaseUrl(baseUrl), model, apiKey: apiKey ?? '' }); diagnosis.value = refined; diagnosisJson.value = JSON.stringify(refined.adapter, null, 2); ElMessage.success(refined.inspection.valid ? 'AI 已根据自检报告完成一次受控调整' : 'AI 已调整候选，但仍有阻断问题'); } catch (error) { ElMessage.error(friendlyIpcMessage(error)) } finally { diagnosisSaving.value = false } }
async function saveDiagnosis(): Promise<void> { diagnosisSaving.value = true; try { const candidate = JSON.parse(diagnosisJson.value); const report = await window.api.ai.inspect(candidate); diagnosis.value = diagnosis.value ? { ...diagnosis.value, adapter: candidate, inspection: report } : null; if (!report.valid) { ElMessage.warning('修复候选仍未通过自检，不能保存'); return }; await window.api.ai.saveAdapter(candidate); diagnosisDialog.value = false; ElMessage.success('修复适配器已保存，当前任务下次执行会自动使用新版') } catch (error) { ElMessage.error(friendlyIpcMessage(error)) } finally { diagnosisSaving.value = false } }
onMounted(() => void load())
</script>

<template>
  <div v-if="task" class="page detail-page">
    <header class="page-header"><div><el-button text :icon="ArrowLeft" @click="router.push('/')">返回任务列表</el-button><div class="detail-title"><div class="large-avatar"><User/></div><div><h1>{{task.site_name}}</h1><p>{{task.account_label||'默认账户'}} · {{task.engine_type.toUpperCase()}} 引擎</p></div><span class="status-pill" :class="`status-${task.last_status||'pending'}`">{{statusLabel(task.last_status)}}</span></div></div><div class="header-actions"><el-button v-if="task.last_status==='failed'" :loading="diagnosisLoading" @click="diagnoseFailure">AI 自检失败原因</el-button><el-button @click="openBrowserSettings">配置登录浏览器</el-button><el-button v-if="task.login_type==='local_browser'" :loading="loginLoading" @click="promptLogin">引导登录并完成首次签到</el-button><el-button class="primary-button" type="primary" :icon="VideoPlay" :loading="running" @click="execute">立即执行</el-button></div></header>
    <section class="metric-grid"><div class="metric panel"><el-icon class="blue-icon"><TrendCharts/></el-icon><div><span>近 20 次成功率</span><strong>{{successRate}}%</strong></div></div><div class="metric panel"><el-icon class="green-icon"><Calendar/></el-icon><div><span>连续签到</span><strong>{{task.consecutive_days}} <small>天</small></strong></div></div><div class="metric panel"><el-icon class="orange-icon"><Timer/></el-icon><div><span>上次执行</span><strong class="time">{{format(task.last_run_at)}}</strong></div></div></section>
    <div class="detail-grid"><section class="panel info-panel"><div class="section-head"><div><h3>任务信息</h3><span>基础配置</span></div></div><dl><div><dt>任务计划</dt><dd>{{task.schedule}}</dd></div><div><dt>登录方式</dt><dd>{{task.login_type}}</dd></div><div><dt>适配器</dt><dd>{{task.adapter_id}}</dd></div><div v-if="localConfig"><dt>浏览器</dt><dd>{{localConfig.channel || 'chrome'}} / {{localConfig.profileName || 'Default'}}</dd></div><div v-if="localConfig"><dt>User Data</dt><dd class="path">{{localConfig.userDataDir || '自动检测'}}</dd></div><div><dt>创建时间</dt><dd>{{format(task.created_at)}}</dd></div></dl></section><section class="panel chart-panel"><div class="section-head"><div><h3>执行趋势</h3><span>最近 {{logs.length}} 次运行结果</span></div></div><div v-if="logs.length" class="mini-chart"><div v-for="(log,index) in logs.slice(0,14).reverse()" :key="log.id" class="bar-wrap"><div class="bar" :class="log.status" :style="{height:`${log.status==='success'?48:20}px`}" :title="`${index+1}: ${statusLabel(log.status)}`"></div></div></div><div v-else class="chart-empty">执行后将在这里显示趋势</div></section></div>
    <section class="panel log-panel"><div class="section-head"><div><h3>执行历史</h3><span>最近 20 条经过脱敏的执行记录</span></div></div><el-table v-if="logs.length" :data="logs"><el-table-column label="时间" width="180"><template #default="{row}">{{format(row.executed_at)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><span class="status-pill" :class="`status-${row.status}`">{{statusLabel(row.status)}}</span></template></el-table-column><el-table-column prop="engine_used" label="引擎" width="90"/><el-table-column prop="duration_ms" label="耗时" width="100"><template #default="{row}">{{row.duration_ms}} ms</template></el-table-column><el-table-column type="expand"><template #default="{row}"><div class="log-detail"><pre>{{row.response_summary||row.error_message||'无附加信息'}}</pre></div></template></el-table-column></el-table><div v-else class="small-empty">暂无执行记录，点击“立即执行”开始第一次签到。</div></section>
    <el-dialog v-model="browserDialog" title="配置登录浏览器" width="600px"><el-form label-position="top"><el-form-item label="登录状态保存方式"><el-radio-group v-model="profileMode"><el-radio-button value="managed">AutoCheckin 专用档案（推荐）</el-radio-button><el-radio-button value="system">复用日常浏览器 Profile</el-radio-button></el-radio-group></el-form-item><div v-if="profileMode==='managed'" class="managed-note"><strong>只需登录一次</strong><span>使用原生 Chrome/Edge，但登录状态保存在任务自己的独立档案中，不会与日常浏览器争抢锁，也不会每次退出 Google 账号。</span></div><template v-else><el-form-item label="浏览器与 Profile"><el-select v-model="browserKey" filterable :loading="browserLoading" placeholder="选择原生 Chrome/Edge Profile"><el-option v-for="option in browserOptions" :key="option.key" :label="option.label" :value="option.key"/><el-option label="自定义 User Data 路径" value="custom"/></el-select></el-form-item><el-form-item v-if="browserKey==='custom'" label="Custom Path"><el-input v-model="customPath" placeholder="Chrome/Edge User Data 目录"/></el-form-item><p class="dialog-help">日常 Profile 正在被 Chrome 使用时仍可能锁定，执行前需完全关闭对应浏览器。</p></template><p v-if="profileMode==='managed'" class="dialog-help">保存后点击“引导登录并完成首次签到”，在打开的窗口里登录并手动成功签到一次，最后关闭整个浏览器窗口。之后后台任务会复用完整状态和已保存的适配器流程。</p></el-form><template #footer><el-button @click="browserDialog=false">取消</el-button><el-button type="primary" @click="saveBrowserSettings">保存配置</el-button></template></el-dialog>
    <el-dialog v-model="diagnosisDialog" title="AI 失败自检与修复候选" width="720px"><div v-if="diagnosis" class="diagnosis-summary"><strong>{{diagnosis.summary}}</strong><span>分类：{{diagnosis.category}} · 置信度 {{Math.round(diagnosis.confidence * 100)}}% · 自检 {{diagnosis.inspection.score}} 分</span><span v-if="diagnosis.requiresManualAction" class="manual-warning">需要用户完成可见登录或安全验证，AI 不会绕过。</span></div><div v-if="diagnosis?.evidence.length" class="diagnosis-evidence"><b>证据</b><span v-for="item in diagnosis.evidence" :key="item">{{item}}</span></div><div v-if="diagnosis?.changes.length" class="diagnosis-evidence"><b>拟调整</b><span v-for="item in diagnosis.changes" :key="item">{{item}}</span></div><div v-if="diagnosis?.inspection.issues.length" class="diagnosis-issues"><p v-for="issue in diagnosis.inspection.issues" :key="`${issue.code}-${issue.path}`"><b>{{issue.severity}}</b> {{issue.path}}：{{issue.message}} <span>{{issue.suggestion}}</span></p></div><el-input v-model="diagnosisJson" type="textarea" :rows="18" class="diagnosis-editor"/><p class="dialog-help">AI 只能读取脱敏日志、生成候选和根据自检报告调整一次；不会读取凭据、Cookie，也不会直接覆盖当前适配器。</p><template #footer><el-button @click="diagnosisDialog=false">取消</el-button><el-button :loading="diagnosisSaving" @click="refineDiagnosis">根据报告调整</el-button><el-button type="primary" :disabled="!diagnosis?.inspection.valid" :loading="diagnosisSaving" @click="saveDiagnosis">确认并保存修复候选</el-button></template></el-dialog>
  </div>
</template>

<style scoped>
.detail-page{max-width:1050px}.page-header{display:flex;justify-content:space-between;align-items:flex-end}.header-actions{display:flex;gap:9px}.detail-title{display:flex;align-items:center;gap:13px;margin-top:15px}.detail-title h1{font-size:24px}.detail-title p{margin-top:5px}.detail-title .status-pill{margin-left:8px}.large-avatar{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,#426fe4,#3157c5);color:#fff}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:15px}.metric{display:flex;align-items:center;gap:14px;padding:18px}.metric>.el-icon{width:40px;height:40px;border-radius:11px;font-size:20px}.blue-icon{background:#edf2ff;color:#4b72dc}.green-icon{background:#eaf8f3;color:#24a87b}.orange-icon{background:#fff4e8;color:#de8d30}.metric span{display:block;color:#8994a7;font-size:10px}.metric strong{display:block;font-size:20px;margin-top:4px}.metric strong small{font-size:11px}.metric .time{font-size:12px}.detail-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:15px;margin-bottom:15px}.chart-panel,.info-panel,.log-panel{padding:20px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.section-head h3{margin:0;font-size:14px}.section-head span{display:block;color:#99a3b2;font-size:10px;margin-top:4px}.info-panel dl{margin:0}.info-panel dl div{display:flex;padding:10px 0;border-bottom:1px solid #eef1f5}.info-panel dl div:last-child{border:0}.info-panel dt{font-size:10px;color:#929cac;width:90px;flex:none}.info-panel dd{margin:0;font-size:10px;font-weight:600;word-break:break-all}.path{font-size:9px!important;font-weight:400!important;color:#78869b}.mini-chart{height:95px;display:flex;align-items:flex-end;gap:9px;border-bottom:1px solid #e8ecf2;padding:0 9px 12px}.bar-wrap{height:60px;flex:1;display:flex;align-items:flex-end}.bar{width:100%;border-radius:4px 4px 1px 1px;min-width:6px}.bar.success{background:#48b58b}.bar.failed{background:#e17073}.chart-empty,.small-empty{height:95px;display:grid;place-items:center;color:#a0a9b7;font-size:11px}.log-panel{padding-bottom:8px}.log-detail{padding:6px 18px 18px}.log-detail pre{white-space:pre-wrap;word-break:break-all;background:#131d2d;color:#b9c7df;border-radius:9px;padding:13px;font-size:10px;max-height:180px;overflow:auto}.small-empty{height:110px}@media(max-width:760px){.page-header,.header-actions{align-items:stretch;flex-direction:column}.metric-grid,.detail-grid{grid-template-columns:1fr}}
.managed-note{margin-bottom:16px;padding:13px 15px;border:1px solid #dfe8ff;border-radius:10px;background:#f4f7ff}.managed-note strong,.managed-note span{display:block}.managed-note span{margin-top:5px;color:#657795;font-size:11px;line-height:1.6}.dialog-help{color:#78869b;font-size:11px;line-height:1.6}
.diagnosis-summary{padding:12px 14px;background:#f3f7ff;border-radius:8px;margin-bottom:12px}.diagnosis-summary strong,.diagnosis-summary span{display:block}.diagnosis-summary strong{font-size:12px}.diagnosis-summary span{font-size:10px;color:#72809a;margin-top:5px}.diagnosis-issues{max-height:150px;overflow:auto;margin-bottom:12px}.diagnosis-issues p{font-size:10px;line-height:1.5;margin:5px 0}.diagnosis-issues b{color:#c04e55}.diagnosis-issues span{color:#77859a}.diagnosis-editor :deep(textarea){font-family:Consolas,monospace;font-size:10px;line-height:1.5;background:#111a2a;color:#c3d2ed}
</style>
